def fill_by_interior_size(grid_work):
    """Fill based on interior_size mapping from demo: 4->2, 5->9, 1->7"""
    result = [row[:] for row in grid_work]

    interior_size_map = {4: 2, 5: 9, 1: 7}

    for color in [0, 3, 6]:
        positions = [(r, c) for r in range(len(result)) for c in range(len(result[0])) if result[r][c] == color]
        if not positions:
            continue
        rmin, rmax = min(r for r, c in positions), max(r for r, c in positions)
        cmin, cmax = min(c for r, c in positions), max(c for r, c in positions)

        interior_h = rmax - rmin - 1
        interior_w = cmax - cmin - 1

        # Use min dimension as "interior_size"
        interior_size = min(interior_h, interior_w)

        fill = interior_size_map.get(interior_size, None)
        if fill is None:
            # Default: large interior gets 2
            fill = 2

        # Fill the interior
        for r in range(rmin + 1, rmax):
            for c in range(cmin + 1, cmax):
                if result[r][c] != color:
                    result[r][c] = fill

    return result

